type Role = 'coach' | 'player' | 'referee';
type Status = 'live' | 'upcoming' | 'finished';
type Team = { id: string; name: string; short: string; city: string; color: string; accent: string; age: string; coach: string; played: number; wins: number; draws: number; losses: number; points: number };
type Player = { id: string; name: string; number: number; position: string; teamId: string; age: number; appearances: number; goals: number; assists: number; rating: number; fitness: number };
type Event = { id: string; minute: number; type: 'goal' | 'yellow' | 'red' | 'foul' | 'sub'; team: 'home' | 'away'; player: string; detail?: string };
type Match = { id: string; competitionId: string; homeId: string; awayId: string; date: string; time: string; venue: string; status: Status; homeScore: number; awayScore: number; minute: number; events: Event[] };
type Competition = { id: string; name: string; short: string; season: string; teams: string[]; color: string; status: string };

function Link({ href, children, ...props }: { href: string; children: ReactNode } & Omit<ComponentProps<typeof RouterLink>, 'to'>) {
  return <RouterLink to={href} {...props}>{children}</RouterLink>;
}

function useLocation() {
  const location = useRouterLocation();
  const navigate = useNavigate();
  return [location.pathname, navigate] as const;
}

function useParams<T extends Record<string, string | undefined>>() {
  return useRouterParams() as T;
}

function Route({ path, component: Component, children }: { path?: string; component?: ComponentType; children?: ReactNode }) {
  return <RouterRoute path={path} element={Component ? <Component /> : <>{children}</>} />;
}

function Switch({ children }: { children: ReactNode }) {
  return (
    <Routes>
      {Children.map(children, (child) => {
        if (!child || typeof child !== 'object' || !('props' in child)) return null;
        const props = (child as React.ReactElement<{ path?: string; component?: ComponentType; children?: ReactNode }>).props;
        const Component = props.component;
        return <RouterRoute key={props.path ?? 'fallback'} path={props.path} element={Component ? <Component /> : <>{props.children}</>} />;
      })}
    </Routes>
  );
}

