const team = (id: string) => teams.find((item) => item.id === id) ?? teams[0];
const player = (id: string) => players.find((item) => item.id === id) ?? players[0];
const competition = (id: string) => competitions.find((item) => item.id === id) ?? competitions[0];
const initials = (name: string) => name.split(' ').map((part) => part[0]).join('').slice(0, 2);
const fmtDate = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });

type Store = { matches: Match[]; setMatches: Dispatch<SetStateAction<Match[]>> };
const MatchStore = createContext<Store | null>(null);
const useMatchStore = () => useContext(MatchStore) as Store;
const useSession = () => {
  const [session, setSession] = useState<{ role: Role; email: string } | null>(() => {
    try { return JSON.parse(localStorage.getItem('academy-session') || 'null'); } catch { return null; }
  });
  useEffect(() => {
    const sync = () => { try { setSession(JSON.parse(localStorage.getItem('academy-session') || 'null')); } catch { setSession(null); } };
    window.addEventListener('academy-session', sync);
    return () => window.removeEventListener('academy-session', sync);
  }, []);
  const login = (role: Role, email: string) => { const value = { role, email }; localStorage.setItem('academy-session', JSON.stringify(value)); setSession(value); window.dispatchEvent(new Event('academy-session')); };
  const logout = () => { localStorage.removeItem('academy-session'); setSession(null); window.dispatchEvent(new Event('academy-session')); };
  return { session, login, logout };
};

