function StatusBadge({ status }: { status: Status | string }) {
  const live = status === 'live' || status === 'In progress';
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${live ? 'bg-[hsl(var(--primary)/.12)] text-[hsl(var(--primary))]' : status === 'upcoming' || status === 'Registration open' ? 'bg-[hsl(var(--accent)/.24)] text-[hsl(var(--foreground))]' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]'}`} data-testid={`status-${status}`}>
    {live && <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-current" />}{status === 'live' ? 'LIVE' : status}
  </span>;
}

function Avatar({ name, color = '#147d58', size = 'md' }: { name: string; color?: string; size?: 'sm' | 'md' | 'lg' }) {
  const sizes = { sm: 'h-7 w-7 text-[10px]', md: 'h-9 w-9 text-xs', lg: 'h-16 w-16 text-lg' };
  return <span className={`grid shrink-0 place-items-center rounded-xl font-display font-bold text-white ${sizes[size]}`} style={{ background: color }} data-testid={`avatar-${name.replaceAll(' ', '-').toLowerCase()}`}>{initials(name)}</span>;
}

function Button({ children, variant = 'primary', className = '', ...props }: { children: ReactNode; variant?: 'primary' | 'ghost' | 'accent' | 'danger'; className?: string } & ButtonHTMLAttributes<HTMLButtonElement>) {
  return <button className={`btn btn-${variant} ${className}`} {...props}>{children}</button>;
}

function MatchCard({ match, compact = false }: { match: Match; compact?: boolean }) {
  const home = team(match.homeId), away = team(match.awayId);
  return <Link href={`/matches/${match.id}`} className={`surface lift block ${compact ? 'p-3' : 'p-4'}`} data-testid={`card-match-${match.id}`}>
    <div className="mb-3 flex items-center justify-between gap-2"><span className="eyebrow">{competition(match.competitionId).short} · {match.venue}</span><StatusBadge status={match.status} /></div>
    <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-3">
      <div className="flex items-center gap-2.5"><span className="grid h-9 w-9 place-items-center rounded-lg text-xs font-bold text-white" style={{ background: home.color }}>{home.short.slice(0, 2)}</span><span className="text-sm font-semibold">{home.name}</span></div>
      <div className="text-center"><div className="font-display text-2xl font-bold tracking-wide">{match.status === 'upcoming' ? match.time : `${match.homeScore} — ${match.awayScore}`}</div>{match.status === 'live' && <div className="font-mono text-[10px] text-[hsl(var(--primary))]">{match.minute}'</div>}{match.status === 'finished' && <div className="text-[10px] text-[hsl(var(--muted-foreground))]">{fmtDate(match.date)}</div>}</div>
      <div className="flex items-center justify-end gap-2.5 text-right"><span className="text-sm font-semibold">{away.name}</span><span className="grid h-9 w-9 place-items-center rounded-lg text-xs font-bold text-white" style={{ background: away.color }}>{away.short.slice(0, 2)}</span></div>
    </div>
  </Link>;
}

