  const { session, logout } = useSession();
  const [open, setOpen] = useState(false);
  return <div className="flex min-h-[100dvh] bg-[hsl(var(--background))]"><Sidebar role={role} open={open} close={() => setOpen(false)} logout={logout} />{open && <button className="fixed inset-0 z-30 bg-black/30 md:hidden" onClick={() => setOpen(false)} aria-label="Close menu" data-testid="button-menu-overlay" /> }<main className="min-w-0 flex-1"><Topbar title={title} subtitle={subtitle} onMenu={() => setOpen(true)} session={session} logout={logout} /><div className="enter mx-auto max-w-[1440px] p-4 md:p-8">{children}</div></main></div>;
